# My Solution:
# Using binary search
# Time Complexity: O(log n)
# Space Complexity: O(1)
def isPowerOfThree(n: int) -> bool:
    if n <= 0:
        return False
    while n % 3 == 0:
        n /= 3
    return n == 1

# Using recursion
# Time Complexity: O(log n)
# Space Complexity: O(1)
def isPowerOfThree(n: int) -> bool:
    if n <= 0:
        return False
    return n == 1 or isPowerOfThree(n / 3)

# Using bit manipulation
# Time Complexity: O(1)
# Space Complexity: O(1)
def isPowerOfThree(n: int) -> bool:
    if n <= 0:
        return False
    if n & (n - 1) == 0:
        return n == 1 or (n & -n) == n
    return False

