// C# code snippet to check extreme hygiene
using System;

class Program {
    static void Main(string[] args) {
        Console.WriteLine("Enter your name:");
        string name = Console.ReadLine();

        Console.WriteLine("Enter your age:");
        int age = Convert.ToInt32(Console.ReadLine());

        Console.WriteLine("Enter your height (in cm):");
        double height = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter your weight (in kg):");
        double weight = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter your gender (m/f):");
        char gender = Convert.ToChar(Console.ReadLine());

        Console.WriteLine("Enter your daily water intake (in liters):");
        double waterIntake = Convert.ToDouble(Console.ReadLine());

        Console.WriteLine("Enter your sleep duration (in hours):");
        double sleepDuration = Convert.ToDouble(Console.ReadLine());

        // Calculate BMI
        double bmi = weight / Math.Pow(height / 100, 2);

        // Determine whether individual has good personal hygiene based on given inputs
        bool hasGoodHygiene = false;
        if (age >= 18 && age <= 65) {
            if (bmi < 25) {
                if (waterIntake >= 1.5 && waterIntake <= 3) {
                    if (sleepDuration >= 7 && sleepDuration <= 9) {
                        hasGoodHygiene = true;
                    }
                }
            }
        }

        // Display result
        if (hasGoodHygiene) {
            Console.WriteLine($"{name}, you have excellent personal hygiene!");
        } else {
            Console.WriteLine($"{name}, you need to improve your personal hygiene.");
        }

    }
}

